def apply_nigeria_contributions(content):
    for old, new in REPLACEMENTS:
        count = content.count(old)
        if count != 1:
            raise ValueError("Nigeria contribution template drift: expected one occurrence, got " + str(count) + " for " + repr(old[:80]))
        content = content.replace(old, new, 1)
    return content
